async function clarify(channel,detail=''){
  if(state.stage!=='clarify'||requestPending)throw Error('Сейчас уточнение не требуется.');
  if(!['retail','business','custom'].includes(channel))throw Error('Выберите тип клиента.');
  detail=bounded(detail,500,'Уточнение');if(channel==='custom'&&!detail)throw Error('Введите уточнение.');
  const text=detail||(channel==='retail'?'Частный клиент · Приобанк Онлайн':'Бизнес или ИП · Интернет-Банк');
  if(sensitive(text))throw Error('Обезличьте уточнение: удалите персональные данные и секретные значения.');
  revision++;state.clarification=text;state.verified=false;state.draft='';state.claims=[];state.sourceIds=[];state.reason='';state.recommendationId=null;state.route={rule:null,direction:null,decision:null};
  emit('clarification',{channel,length:text.length});
  if(injection(text)){state.mode='guard';insufficient('Уточнение содержит команды изменить правила. Оно не отправлено модели. Нужны тип клиента и название сервиса.');finishRecommendation();return getState();}
  return requestModel();
}
function loadConfig(){
  try{const data=window.OperatorAI.config();aiConfig={status:'ready',model:typeof data.model==='string'?data.model:null,configured:data.configured===true,provider:'local',budgetLimit:null};}
  catch{aiConfig={status:'unavailable',model:null,configured:false,provider:'local',budgetLimit:null};}
  renderConnection();
}
function renderConnection(){
  const label=$('#ai-connection');if(!label)return;
  label.textContent=aiConfig.status==='checking'?'Проверка локальной модели…':aiConfig.status==='unavailable'?'Локальная модель недоступна':aiConfig.configured?('Локальная модель: '+(aiConfig.model||'Qwen')+' · без платы за API'):'Для локальной модели нужен браузер с WebGPU';
}
function claimsHtml(){
  if(state.edited)return '<li>После правки проверяйте связь тезисов с основаниями вручную. Разметка модели снята и автоматически не восстанавливается.</li>';
  return state.claims.map((claim,i)=>`<li>Тезис ${i+1}: ${esc(claim.text)} ${claim.sourceIds.map(id=>{const n=state.sourceIds.indexOf(id)+1;return `<button data-source="${esc(id)}" aria-label="Основание ${n} для тезиса ${i+1}">[${n}]</button>`;}).join('')}</li>`).join('');
}
function generationHtml(){
  if(state.mode==='control')return '<p class="generation-meta">Учебный контрольный сценарий · выполнен локально · без вызова модели.</p>';
  if(state.mode==='retrieval')return '<p class="generation-meta">Локальный поиск не нашёл подходящих оснований. Языковая модель не вызывалась; это не сгенерированный AI-ответ.</p>';
  if(state.mode==='guard')return '<p class="generation-meta">Локальная проверка ввода · запрос модели не отправлен.</p>';
  if(state.mode!=='ai'||state.stage==='loading')return '';
  const detail=[state.model?('Модель: '+state.model):null,state.elapsedMs!==null?((state.elapsedMs/1000).toFixed(1)+' с'):null,state.usage?('Токены: '+state.usage.inputTokens+' вход / '+state.usage.outputTokens+' выход'):null].filter(Boolean).join(' · ');
  return `<p class="generation-meta">${state.stage==='error'?'Ответ AI не получен':esc(detail||'Ответ получен от локальной модели')}. Черновик проверяет оператор.</p>`;
}
function verify(){if(state.stage!=='answer'||!state.draft.trim())throw Error('Нужен непустой черновик ответа.');if(state.invalidated||state.sourceIds.some(id=>!allowed(sources[id])))throw Error('Основания изменились. Выполните поиск заново.');if(sensitive(state.draft))throw Error('В черновике обнаружены возможные персональные данные или секрет. Обезличьте текст.');state.verified=true;state.copied=false;emit('review',{sourceVersions:clone(state.sourceVersions),edited:state.edited});render();return getState();}
function updateDraft(text,redraw=true){if(state.stage!=='answer')throw Error('Редактирование доступно для черновика ответа.');text=bounded(text,5000,'Черновик');revision++;state.draft=text;state.edited=true;state.claims=[];state.editing=true;state.verified=false;state.copied=false;emit('draft_edited',{length:text.length});if(redraw)render();else{$('#edit-state').textContent='Изменено оператором · проверку нужно повторить';$('#result-status').textContent=state.invalidated?'Основания изменились':'Черновик изменён';$('#result-status').className='status '+(state.invalidated?'danger':'warning');const claims=$('.claim-list');if(claims)claims.innerHTML='<li>После правки проверяйте связь тезисов с основаниями вручную. Предыдущая разметка тезисов снята.</li>';$('#copy').disabled=true;$('#verify-draft').disabled=!text.trim()||state.invalidated;$('#copy-note').textContent='После правки проверьте все тезисы заново.';}return getState();}
function routeDecision(decision){if(!['accepted','rejected'].includes(decision))throw Error('Решение: accepted или rejected.');if(!state.recommendationId||state.stage==='empty'||state.stage==='blocked')throw Error('Сначала подготовьте рекомендацию.');state.route.decision=decision;emit('route_decision',{decision,rule:state.route.rule,direction:state.route.direction});render();return getState();}
function handoff(){if(!state.recommendationId||state.stage==='empty'||state.stage==='blocked')throw Error('Сначала подготовьте обезличенное обращение.');const reason=state.reason||'Оператор просит проверить ответ и применимость оснований.';state.handoffText=['УЧЕБНЫЙ ЗАПРОС — НЕ ОТПРАВЛЕН','Обращение: '+state.question,'Тема: '+topicName(state.topic),'Уточнения: '+(state.clarification||'не получены'),'Основания: '+(state.sourceIds.map(id=>sources[id].title+' / версия '+sources[id].version).join('; ')||'достаточные основания не найдены'),'Выполнено: '+(state.mode==='ai'?'запрос локальной модели по публичным материалам':state.mode==='control'?'локальный учебный сценарий':state.mode==='retrieval'?'локальный поиск без вызова модели':'проверка ввода')+'; '+(state.verified?'оператор отметил проверку':'проверка ответа не завершена')+'; решение по рекомендации: '+(state.route.decision==='accepted'?'принята':state.route.decision==='rejected'?'отклонена':'не принято'),'Причина запроса: '+reason,'Направление: '+(state.route.direction||'не определено — заполнить по внутреннему регламенту')].join('\n');state.handoffEdited=false;emit('handoff_created',{rule:state.route.rule,sourceVersions:clone(state.sourceVersions)});render();return getState();}
function updateHandoff(text){text=bounded(text,5000,'Запрос специалисту');state.handoffText=text;state.handoffEdited=true;revision++;emit('handoff_edited',{length:text.length});return getState();}
function feedback(useful,reason=''){if(!state.recommendationId||state.stage==='blocked')throw Error('Сначала получите рекомендацию.');if(typeof useful!=='boolean')throw Error('Оценка должна быть true или false.');const allowedReasons=['Подтверждённый ответ','Неверный факт','Устаревший источник','Неполный ответ','Нерелевантный поиск','Недостаточно оснований','Конфликт документов','Неудобная формулировка','Другое'];if(!allowedReasons.includes(reason))throw Error('Выберите причину оценки из списка.');state.feedback={useful,reason};emit('feedback',{useful,reason,sourceVersions:clone(state.sourceVersions)});render();return getState();}
function invalidate(reason){if(!state.recommendationId)return;revision++;state.verified=false;state.copied=false;state.invalidated=true;state.handoffText='';emit('recommendation_invalidated',{reason,sourceVersions:clone(state.sourceVersions)});}
function setSourceStatus(id,status,internal=false){if(!internal&&role!=='owner')throw Error('Изменять статусы может учебная роль владельца знаний. Это модель прав в браузере.');if(!sources[id])throw Error('Материал не найден.');if(!Object.hasOwn(statusLabels,status))throw Error('Неизвестный статус.');cancelGeneration('Изменился статус материала');revision++;const previous=sources[id].status;if(previous===status)return getState();sources[id].status=status;emit('source_status_changed',{sourceId:id,previous,status,version:sources[id].version});if(state.sourceIds.includes(id))invalidate('Изменился статус источника '+id);render();return getState();}
function setRole(next){if(!['operator','owner','analyst'].includes(next))throw Error('Неизвестная учебная роль.');cancelGeneration('Изменена учебная роль');$('#source-dialog').close();$('#materials-dialog').close();role=next;if(role!=='owner'&&state.sourceIds.some(id=>sources[id].status==='restricted')){invalidate('Материал недоступен выбранной учебной роли');state.draft='';state.caseId=null;state.stage='insufficient';state.reason='Основание стало недоступно выбранной учебной роли. Нужен доступный материал или специалист.';state.excluded=state.sourceIds.map(id=>({id,eligible:false,reason:excludedReason(sources[id])}));state.sourceIds=[];}$('#role-select').value=role;state.verified=false;state.copied=false;revision++;emit('role_changed');if(role==='analyst')view='log';else if(view==='owner'&&role!=='owner')view='workspace';render();return getState();}
function reset(){cancelGeneration('Новое обращение');revision++;state=emptyState();$('#question').value='';$('#topic').value='';$('#question-error').textContent='';inputCount();emit('reset');render();return getState();}
function restoreSources(){cancelGeneration('Набор материалов восстановлен');revision++;sources=structuredClone(sourceTemplates);if(state.sourceIds.length)invalidate('Учебный набор восстановлен');emit('source_status_changed',{sourceId:'all',status:'restored'});render();}
function loadDemo(name){const demo=DK.demos.find(d=>d.id===name)||(name==='control'||name==='answer-control'?{id:'control',topic:'control',question:'Куда передать контрольную заявку TEST-42?'}:null);if(!demo)throw Error('Неизвестный сценарий.');if(role==='analyst')setRole('operator');restoreSources();if(name==='conflict')setSourceStatus('demo-conflict','active',true);emit('demo_started',{scenario:name,scenarioDate:SCENARIO_DATE});view='workspace';return prepare(demo.question,demo.topic,['error','timeout'].includes(name)?name:null);}
function exportLog(){emit('export_requested');return clone({schemaVersion:1,prototypeVersion:DK.version,scenarioDate:SCENARIO_DATE,scope:'session-only events; no question or draft text; local model inference in browser; model resources may be downloaded',events});}
async function copy(target='draft'){
  if(copyPending)throw Error('Предыдущая операция копирования ещё не завершилась.');
  if(!['draft','handoff'].includes(target))throw Error('Неизвестный текст для копирования.');
  const text=target==='handoff'?state.handoffText:state.draft;
  if(!text.trim())throw Error('Нет текста для копирования.');
  if(target==='draft'&&(!state.verified||state.invalidated||state.stage!=='answer'||state.sourceIds.some(id=>!allowed(sources[id]))))throw Error('Проверьте текущий ответ и применимость источников.');
  if(sensitive(text))throw Error('Перед копированием удалите возможные персональные данные и секреты.');
  const activeRevision=revision,activeRec=state.recommendationId,token=++copyToken;copyPending=true;render();
  let timedOut=false;const fallback=()=>{if(activeRevision!==revision||activeRec!==state.recommendationId)return;const field=$(target==='handoff'?'#handoff-text':'#draft');if(field){field.focus();field.select();}notify('Текст выделен. Скопируйте его вручную: Ctrl+C / ⌘C.');};
  const timer=setTimeout(()=>{timedOut=true;fallback();},1600);
  try{if(!navigator.clipboard?.writeText)throw Error('Нет доступа к буферу');await navigator.clipboard.writeText(text);if(!timedOut&&activeRevision===revision&&activeRec===state.recommendationId){state.copied=true;emit('copy',{target,length:text.length});notify('Текст скопирован. Сообщение не отправлено.');}}
  catch{fallback();}finally{clearTimeout(timer);if(token===copyToken)copyPending=false;render();}return getState();
}
function statusMetadata(s){const validity=s.synthetic?((s.validFrom||'?')+' — '+(s.validTo||'?')):'не установлены · проверить в оригинале';return `<dl class="source-metadata"><dt>Владелец</dt><dd>${esc(s.owner)}</dd><dt>Версия</dt><dd>${esc(s.version)}</dd><dt>Срок действия</dt><dd>${esc(validity)}</dd><dt>Статус модели</dt><dd>${esc(statusLabels[s.status])}</dd><dt>${s.synthetic?'Дата сценария':'Дата снимка'}</dt><dd>${s.synthetic?'14.10.2026':KB.checked}</dd></dl>`;}
function sourceCard(id,index,excluded=false,why=''){const s=sources[id];if(s.status==='restricted'&&role!=='owner')return `<article class="evidence-card excluded"><span class="source-ref">Исключён</span><h3>Материал недоступен</h3><p class="fine">ID: ${esc(id)}. Содержание скрыто для выбранной учебной роли.</p><p class="exclusion-reason">Нет доступа оператора</p></article>`;return `<article class="evidence-card ${excluded?'excluded':''}" data-evidence="${esc(id)}"><div class="source-topline"><span class="source-ref">${excluded?'Исключён':'['+index+']'}</span><span class="source-badge ${s.synthetic?'synthetic':''}">${s.synthetic?'Учебный документ':'Публичный пересказ'}</span></div><h3>${esc(s.title)}</h3><p class="source-section">${esc(s.section)}</p><blockquote class="excerpt">${esc(s.fragments.join(' '))}</blockquote><p class="fine">${s.synthetic?'Точный фрагмент синтетического контрольного документа.':'Пересказ изученного материала. Точная цитата из оригинала не верифицирована.'}</p>${statusMetadata(s)}${excluded?`<p class="exclusion-reason">${esc(why)}</p>`:''}<button class="source-open" data-source="${esc(id)}">${s.synthetic?'Открыть учебный материал':'Открыть материал и оригинал'} →</button></article>`;}
function renderEvidence(){const eligible=state.sourceIds;$('#evidence-count').textContent=eligible.length;const excluded=state.excluded.filter(r=>!eligible.includes(r.id));if(!eligible.length&&!excluded.length){$('#evidence').innerHTML=`<div class="empty-state"><span class="empty-icon" aria-hidden="true">≡</span><h3>${state.stage==='error'?'Продолжите вручную':'Документы рядом с ответом'}</h3><p>${state.stage==='error'?'Откройте базу материалов и сохраните вопрос для ручной обработки.':'Найденные фрагменты, версии и ограничения появятся после поиска.'}</p><small>11 публичных источников<br>+ отдельный учебный контрольный набор</small></div>`;return;}$('#evidence').innerHTML=`<div class="evidence-body"><p class="retrieval-note">Тема: ${esc(topicName(state.topic))}. Использовано: ${eligible.length}; исключено: ${excluded.length}. ${state.mode==='ai'?'Локальная модель работает с фиксированным набором публичных пересказов. Это не подключение к базе банка.':state.mode==='control'?'Локальный учебный контрольный набор, без вызова модели.':'Локальный поиск публичных пересказов, без вызова модели.'}</p>${eligible.map((id,i)=>sourceCard(id,i+1)).join('')}${excluded.map(r=>sourceCard(r.id,0,true,r.reason)).join('')}</div>`;}
function routeHtml(){const noRule=!state.route.rule;return `<div class="routing"><h3>Передача специалисту</h3><strong>${esc(state.route.direction||'Направление не определено')}</strong><p>${noRule?'Внутреннего правила маршрутизации нет в публичном наборе. Оператор определяет направление по регламенту банка.':'Учебное правило '+esc(state.route.rule)+'. Синтетическое направление для демонстрации.'}</p><div class="route-actions"><button id="route-accept" class="secondary">${noRule?'Нужна передача':'Принять рекомендацию'}</button><button id="route-decline" class="secondary">Отклонить</button></div>${state.route.decision?`<p class="route-choice">${state.route.decision==='accepted'?'Оператор принял решение о передаче'+(noRule?'; направление требует заполнения':''):'Оператор отклонил рекомендацию'}</p>`:''}<button id="create-handoff" class="text-button">Подготовить запрос специалисту →</button></div>`;}
function handoffHtml(){if(!state.handoffText)return '';return `<div class="routing"><h3>Запрос для ручной передачи</h3><p class="fine">Отредактируйте направление и контекст. Это текст для оператора; отправка не выполняется.</p><label for="handoff-text" class="hand-label">Обезличенный контекст обращения</label><textarea id="handoff-text" maxlength="5000"></textarea><button id="copy-handoff" class="secondary">Скопировать запрос</button></div>`;}
function feedbackHtml(){const reasons=['Подтверждённый ответ','Неверный факт','Устаревший источник','Неполный ответ','Нерелевантный поиск','Недостаточно оснований','Конфликт документов','Неудобная формулировка','Другое'];return `<div class="feedback-box"><h3>Помогла ли рекомендация?</h3><p class="fine">Оценка связана с ${esc(state.recommendationId)} и версиями оснований.</p><label for="feedback-reason">Причина</label><select id="feedback-reason" class="feedback-reason">${reasons.map(r=>`<option ${state.feedback?.reason===r?'selected':''}>${esc(r)}</option>`).join('')}</select><div class="feedback-actions"><button id="feedback-useful" class="secondary">Полезно</button><button id="feedback-not" class="secondary">Не полезно</button></div>${state.feedback?`<p class="feedback-result">Сохранено в этой сессии: ${state.feedback.useful?'полезно':'не полезно'} · ${esc(state.feedback.reason)}</p>`:''}</div>`;}
function renderResult(){let html='',status='Ожидает вопроса',statusClass='';
  if(state.stage==='loading'){status='Модель готовит ответ';statusClass='warning';html=`<div class="empty-state loading-state"><span class="loading-spinner" aria-hidden="true"></span><h3>${state.loadingPhase==='generating'?'Модель готовит черновик':'Загружаем локальную модель'}</h3><p>${esc(state.loadingMessage)}</p><button id="cancel-generation" class="secondary">Отменить ожидание</button><small>Первый запуск загружает около 300 МБ. После загрузки модель работает в браузере; запрос не отправляется в AI-сервис.</small></div>`; }
  else if(state.stage==='empty')html='<div class="empty-state"><span class="empty-icon" aria-hidden="true">✎</span><h3>Начните с темы и вопроса</h3><p>Получите черновик вместе с основаниями. Окончательное решение остаётся за оператором.</p><small>Готовые примеры находятся в разделе «Демонстрация».</small></div>';
  else{const history=state.clarification?`<div class="clarification-history"><strong>Уточнение:</strong> ${esc(state.clarification)}</div>`:'';
    html=`<div class="result-body"><div class="result-kicker"><span>${esc(topicName(state.topic))}</span><span>${esc(state.recommendationId)}</span></div>${history}${generationHtml()}`;
    if(state.stage==='answer'){status=state.invalidated?'Основания изменились':state.copied?'Скопировано':state.verified?'Проверен оператором':state.edited?'Черновик изменён':'Черновик готов';statusClass=state.invalidated?'danger':state.edited&&!state.verified?'warning':'ready';html+=state.invalidated?'<div class="notice danger"><h3>Черновик требует обновления</h3><p>Статус одного из оснований изменился. Проверка и копирование заблокированы. Выполните поиск заново.</p><button id="refresh-search" class="secondary">Повторить поиск</button></div>':'<div class="review-note">Сверьте каждый тезис с оригиналом и проверьте применимость условий. Отметка ниже — подтверждение оператора.</div>';
      html+=`<label for="draft">Текст ответа</label><textarea id="draft" maxlength="5000" ${state.editing?'':'readonly'}></textarea><p id="edit-state" class="editor-meta">${state.edited?'Изменено оператором · проверку нужно повторить':state.mode==='ai'?'Черновик модели · разрешена правка':'Учебный шаблон · разрешена правка'}</p><ol class="claim-list">${claimsHtml()}</ol><div class="result-actions"><button id="edit" class="secondary">${state.editing?'Завершить правку':'Редактировать'}</button><button id="verify-draft" class="secondary" ${state.invalidated||!state.draft.trim()?'disabled':''}>${state.verified?'Проверку повторить':'Я проверил ответ'}</button><button id="copy" class="primary" ${!state.verified||state.invalidated||!state.draft.trim()||copyPending?'disabled':''}>Копировать</button></div><p id="copy-note" class="copy-note ${state.copied?'success':''}">${state.copied?'Скопирован текущий текст; сообщение не отправлено.':state.verified?'Отметка оператора получена. Копируется текст из поля выше.':'Проверьте оригинал, каждый тезис и применимость условий перед копированием.'}</p>`;
    }else if(state.stage==='clarify'){status='Нужно уточнение';statusClass='warning';html+=`<div class="notice"><h3>Нужно уточнить обращение</h3><p>${esc(state.reason)}</p></div><div class="clarification-options"><button class="secondary" data-channel="retail">Частный клиент</button><button class="secondary" data-channel="business">Бизнес или ИП</button></div><form id="clarification-form" class="clarification-form"><label for="clarification">Или своё уточнение</label><input id="clarification" maxlength="500" placeholder="Тип клиента, название и версия сервиса"><button class="primary" type="submit">Продолжить с уточнением</button></form><p id="clarification-error" class="error" aria-live="polite"></p>`;
    }else{status={insufficient:'Недостаточно оснований',conflict:'Конфликт документов',error:'Ручное продолжение',blocked:'Обезличьте вопрос'}[state.stage]||'Требуется проверка';statusClass=state.stage==='error'||state.stage==='blocked'?'danger':'warning';html+=`<div class="notice ${state.stage==='error'||state.stage==='blocked'?'danger':''}"><h3>${esc(status)}</h3><p>${esc(state.reason)}</p></div><ul class="missing">${state.missing.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`;if(state.stage==='error')html+='<button id="manual-knowledge" class="primary">Открыть ручную базу</button><button id="refresh-search" class="text-button">Повторить запрос →</button>';}
    if(state.stage!=='blocked')html+=routeHtml()+handoffHtml()+feedbackHtml();html+='</div>';
  }
  $('#result').innerHTML=html;$('#result').setAttribute('aria-busy',String(requestPending));$('#generate').disabled=requestPending;$('#generate').textContent=requestPending?'Модель готовит ответ…':'Подготовить с AI';$('#cancel-generation')?.addEventListener('click',()=>{cancelGeneration('Оператор отменил ожидание');revision++;render();notify('Ожидание отменено. Вопрос сохранён. Загруженные файлы модели могут остаться в кэше браузера.');});$('#result-status').textContent=status;$('#result-status').className='status '+statusClass;
  if($('#draft')){$('#draft').value=state.draft;$('#draft').addEventListener('input',e=>updateDraft(limitInput(e.target,5000),false));}
  if($('#handoff-text')){$('#handoff-text').value=state.handoffText;$('#handoff-text').addEventListener('input',e=>updateHandoff(limitInput(e.target,5000)));}
  $('#edit')?.addEventListener('click',()=>{state.editing=!state.editing;render();if(state.editing)$('#draft').focus();});
  $('#verify-draft')?.addEventListener('click',()=>safe(verify));$('#copy')?.addEventListener('click',()=>safe(()=>copy()));$('#copy-handoff')?.addEventListener('click',()=>safe(()=>copy('handoff')));
  $('#route-accept')?.addEventListener('click',()=>safe(()=>routeDecision('accepted')));$('#route-decline')?.addEventListener('click',()=>safe(()=>routeDecision('rejected')));$('#create-handoff')?.addEventListener('click',()=>safe(handoff));
  $('#feedback-useful')?.addEventListener('click',()=>safe(()=>feedback(true,$('#feedback-reason').value)));$('#feedback-not')?.addEventListener('click',()=>safe(()=>feedback(false,$('#feedback-reason').value)));
  $('#clarification')?.addEventListener('input',e=>limitInput(e.target,500));document.querySelectorAll('[data-channel]').forEach(b=>b.addEventListener('click',()=>safe(()=>clarify(b.dataset.channel))));
  $('#clarification-form')?.addEventListener('submit',async e=>{e.preventDefault();const text=$('#clarification').value;try{await clarify('custom',text);}catch(err){if($('#clarification-error'))$('#clarification-error').textContent=err.message;else notify(err.message);}});
  $('#manual-knowledge')?.addEventListener('click',openMaterials);$('#refresh-search')?.addEventListener('click',()=>safe(()=>prepare(state.question,state.topic)));
}
function renderOwner(){$('#owner-sources').innerHTML=Object.values(sources).map(s=>`<div class="owner-row"><div><h3>${esc(s.title)}</h3><p>${s.synthetic?'Учебный документ':'Публичный пересказ'} · версия ${esc(s.version)} · ${esc(s.id)}</p></div><label class="sr-only" for="status-${esc(s.id)}">Статус ${esc(s.title)}</label><select id="status-${esc(s.id)}" data-status-source="${esc(s.id)}" aria-label="Статус ${esc(s.title)}">${Object.entries(statusLabels).map(([id,label])=>`<option value="${id}" ${s.status===id?'selected':''}>${esc(label)}</option>`).join('')}</select><span class="status ${s.status==='active'?'ready':'warning'}">${s.synthetic?'Учебная дата: 14.10.2026':'Срок банка неизвестен'}</span></div>`).join('');document.querySelectorAll('[data-status-source]').forEach(el=>el.addEventListener('change',()=>safe(()=>setSourceStatus(el.dataset.statusSource,el.value))));}
function renderLog(){$('#log-events').innerHTML=events.length?events.slice().reverse().map(e=>`<div class="log-item"><span>${e.id}</span><div><strong>${esc(labels[e.type]||e.type)}</strong><br><time>${esc(e.time.slice(11,19))} UTC</time></div><code>${esc(JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k])=>!['id','time','type'].includes(k)))))}</code></div>`).join(''):'<div class="empty-state"><h3>Сессия только началась</h3><p>После действий оператора здесь появятся события.</p></div>';}
function render(){
  $('#owner-tab').hidden=role!=='owner';$('#workspace-tab').hidden=role==='analyst';$('#demo-tab').hidden=role==='analyst';
  document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});
  $('#operator-workspace').hidden=!['workspace','demo'].includes(view)||role==='analyst';$('#demo-panel').hidden=view!=='demo'||role==='analyst';$('#knowledge-owner').hidden=view!=='owner'||role!=='owner';$('#event-log').hidden=view!=='log';
  renderResult();renderEvidence();if(role==='owner')renderOwner();if(view==='log')renderLog();
  document.querySelectorAll('[data-source]').forEach(b=>b.addEventListener('click',()=>safe(()=>openSource(b.dataset.source))));
}
function safe(fn){try{const result=fn();if(result?.catch)result.catch(e=>notify(e.message));return result;}catch(e){notify(e.message);return null;}}
function openSource(id){const s=sources[id];if(!s)throw Error('Материал не найден.');if(role==='analyst'||s.status==='restricted'&&role!=='owner')throw Error('Материал недоступен для выбранной учебной роли.');$('#source-content').innerHTML=`<h2 id="source-title">${esc(s.title)}</h2><span class="source-summary-label">${s.synthetic?'Учебный точный фрагмент':'Пересказ · не верифицированная цитата'}</span><p class="source-section">${esc(s.section)}</p><blockquote class="excerpt">${esc(s.summary)}</blockquote>${statusMetadata(s)}<p class="fine" style="margin-top:18px">${esc(s.caveat)}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Открыть официальный оригинал ↗</a>`:'<p class="fine">Синтетический материал для проверки прототипа. Публичного оригинала нет.</p>'}`;$('#source-dialog').showModal();return clone(s);}
function renderMaterials(){const text=norm($('#kb-search').value);const visible=Object.values(sources).filter(s=>role!=='analyst'&&(s.status!=='restricted'||role==='owner')&&norm(s.title+' '+s.summary).includes(text));$('#materials-list').innerHTML=visible.map(s=>`<article class="material-item"><span class="source-badge ${s.synthetic?'synthetic':''}">${s.synthetic?'Учебный документ':'Публичный пересказ'}</span><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p>${statusMetadata(s)}<p class="fine">${esc(s.caveat)}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Официальный источник ↗</a>`:''}</article>`).join('')||'<p class="fine" style="margin-top:20px">Подходящих материалов нет.</p>';}
function openMaterials(){if(role==='analyst')throw Error('Учебному аналитику доступен только журнал.');$('#kb-search').value='';renderMaterials();emit('manual_knowledge_opened');$('#materials-dialog').showModal();}
function downloadLog(){const data=exportLog(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='operator-session.json';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);renderLog();}
$('#topic').innerHTML+='<option disabled>──────────────</option>'+DK.topics.map(t=>`<option value="${t.id}">${esc(t.label)}</option>`).join('');
$('#demo-case').innerHTML=DK.demos.map(d=>`<option value="${d.id}">${esc(d.label)}</option>`).join('')+'<option value="control">Учебный ответ TEST-42</option>';
$('#example-list').innerHTML=KB.cases.map(c=>`<button class="example-button" data-example="${esc(c.id)}">${esc(c.label)}</button>`).join('');
$('#question-form').addEventListener('submit',async e=>{e.preventDefault();try{await prepare($('#question').value,$('#topic').value);$('#result-heading').focus({preventScroll:true});}catch(err){$('#question-error').textContent=err.message;}});
$('#question').addEventListener('input',e=>{limitInput(e.target,1200);inputCount();if(requestPending){cancelGeneration('Изменён вопрос');revision++;render();}if(state.recommendationId&&e.target.value.trim()!==state.question){if(!state.invalidated)invalidate('Вопрос изменён');render();}});
$('#topic').addEventListener('change',()=>{if(requestPending){cancelGeneration('Изменена тема');revision++;render();}if(state.recommendationId&&$('#topic').value!==state.topic){if(!state.invalidated)invalidate('Тема изменена');render();}});
$('#reset').addEventListener('click',()=>{reset();$('#question').focus();});$('#role-select').addEventListener('change',e=>safe(()=>setRole(e.target.value)));
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render();}));
$('#run-demo').addEventListener('click',()=>safe(()=>loadDemo($('#demo-case').value)));document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{const c=getCase(b.dataset.example);view='workspace';safe(()=>prepare(c.question,DK.caseTopics[c.id]));}));
$('#restore-sources').addEventListener('click',()=>safe(()=>{if(role!=='owner')throw Error('Нужна учебная роль владельца знаний.');restoreSources();}));$('#export-log').addEventListener('click',()=>safe(downloadLog));$('#materials').addEventListener('click',()=>safe(openMaterials));$('#kb-search').addEventListener('input',e=>{limitInput(e.target,200);renderMaterials();});
$('#close-source').addEventListener('click',()=>$('#source-dialog').close());$('#return-to-draft').addEventListener('click',()=>$('#source-dialog').close());$('#close-materials').addEventListener('click',()=>$('#materials-dialog').close());
for(const id of ['source-dialog','materials-dialog']){const d=$('#'+id);let focusBefore=null;d.addEventListener('close',()=>{focusBefore?.focus?.();focusBefore=null;});d.addEventListener('keydown',e=>{if(e.key==='Tab'&&d.open){const controls=Array.from(d.querySelectorAll('button,a[href],input,select,textarea,[tabindex]')).filter(el=>!el.disabled&&!el.hidden&&el.tabIndex>=0&&el.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});const original=d.showModal.bind(d);d.showModal=()=>{focusBefore=document.activeElement;original();};}
window.OperatorDemo=Object.freeze({getState,prepare,clarify,setRole,setSourceStatus,verify,updateDraft,routeDecision,handoff,updateHandoff,feedback,loadDemo,reset,exportLog,copy,openSource,openMaterials,retrieve:(q,t)=>clone(retrieve(q,t)),restoreSources:()=>{if(role!=='owner')throw Error('Нужна учебная роль владельца знаний.');restoreSources();return getState();}});
inputCount();render();renderConnection();loadConfig();
